export const UFCModel: SportPredictionModel = {
  sportKey: UFC_SPORT_KEY,
  sportKeyPrefixes: [UFC_SPORT_KEY, "mma_"],
  uiLabel: "MMA",
  modelVersion: UFC_MODEL_VERSION,
  supportedMarkets: ["h2h"],
  dataContract: UFC_CONTRACT,

  supportsMarket(market: string): boolean {
    return market === "h2h";
  },

  async loadContext(deps: ModelDeps): Promise<ModelContext> {
    let fighters: any[] = [];
    try {
      fighters = await pagedUfc(deps, "fighters?select=fighter_id,full_name,division,stance,height_inches,reach_inches,age,wins,losses,draws", "full_name", 20);
    } catch (e) {
      return {
        status: "insufficient_data",
        missing: ["ufc.fighters"],
        detail: `ufc schema unreadable: ${String((e as Error)?.message ?? e)}. Expose the "ufc" schema under Supabase > API settings > Exposed schemas.`,
      };
    }
    if (!fighters.length) {
      return { status: "insufficient_data", missing: ["ufc.fighters rows"], detail: "ufc schema reachable but the fighter table is empty." };
    }

    let fights: any[] = [];
    try {
      fights = await pagedUfc(deps, "fighter_fights?select=fighter_id,opponent_id,date,winner,method,round,went_distance", "date.asc", 40);
    } catch (e) {
      return { status: "insufficient_data", missing: ["ufc.fighter_fights"], detail: String((e as Error)?.message ?? e) };
    }

    const built = buildFighterElo(fights);
    const minFights = envNum("UFC_MIN_FIGHTS", 400);
    if (built.used < minFights) {
      return {
        status: "insufficient_data",
        missing: [`ufc.fighter_fights usable bouts (have ${built.used}, need >= ${minFights})`],
        detail: built.semantics === "unknown"
          ? "ufc.fighter_fights.winner could not be interpreted as either a fighter id or a W/L result, so no rating can be built."
          : `Only ${built.used} bouts resolved to a winner. No predictions written.`,
      };
    }

    const career = new Map<string, FighterCareer>();
    const style = new Map<string, FighterStyle>();
    const derived = new Map<string, FighterDerived>();
    // Optional tables: their absence degrades the matchup features, it does not
    // stop the rating, so each is tried independently and reported.
    const optionalMissing: string[] = [];
    try {
      const rows = await pagedUfc(deps, "fighter_career_stats?select=fighter_id,slpm,sapm,striking_accuracy,striking_defense,takedown_avg,takedown_accuracy,takedown_defense,submission_avg,knockdown_avg,control_time_avg", "fighter_id", 20);
      for (const r of rows) if (r?.fighter_id != null) career.set(String(r.fighter_id), r);
    } catch (_) { optionalMissing.push("ufc.fighter_career_stats"); }
    try {
      const rows = await pagedUfc(deps, "fighter_style_metrics?select=fighter_id,primary_style,distance_striker,pressure_striker,counter_striker,wrestler,submission_specialist,grappler,high_output,power_striker,durability_score,finisher", "fighter_id", 20);
      for (const r of rows) if (r?.fighter_id != null) style.set(String(r.fighter_id), r);
    } catch (_) { optionalMissing.push("ufc.fighter_style_metrics"); }
    try {
      const rows = await pagedUfc(deps, "fighter_derived_metrics?select=fighter_id,finish_rate,finish_rate_last5,win_streak,loss_streak,days_since_last_fight,activity_last365,title_fight_experience,opponent_average_win_pct,average_fight_time", "fighter_id", 20);
      for (const r of rows) if (r?.fighter_id != null) derived.set(String(r.fighter_id), r);
    } catch (_) { optionalMissing.push("ufc.fighter_derived_metrics"); }

    const bio = new Map<string, FighterBio>();
    for (const f of fighters) {
      if (f?.fighter_id == null) continue;
      bio.set(String(f.fighter_id), { ...f, fighter_id: String(f.fighter_id), full_name: String(f.full_name ?? "") });
    }
    const nameIndex = buildNameIndex(
      Array.from(bio.values()).filter((b) => b.full_name).map((b) => ({ id: b.fighter_id, name: b.full_name })),
    );

    const lastFight = new Map<string, string>();
    for (const [id, dt] of built.elo.lastDate) lastFight.set(id, dt);

    let fitted: UfcCtxData["fitted"] = null;
    try {
      const rows = await deps.sbGet(
        `model_parameters?select=params,fitted_at,metrics&model_version=eq.${encodeURIComponent(UFC_MODEL_VERSION)}&param_set=eq.default&limit=1`,
      );
      const p = rows?.[0]?.params;
      if (p?.blend?.weights?.length === UFC_FEATURES.length) {
        fitted = { ...p.blend, fitted_at: rows[0].fitted_at, metrics: rows[0].metrics };
      }
    } catch (_) { /* no calibration stored yet */ }

    const data: UfcCtxData = {
      elo: built.elo,
      nameIndex,
      bio,
      career,
      style,
      derived,
      lastFight,
      fightsUsed: built.used,
      historyThrough: built.through,
      fitted,
      index: buildMarketIndex([]),
    };
    return {
      status: "ok",
      dataAsOf: built.through,
      featureSnapshotId: `${UFC_MODEL_VERSION}:${built.through ?? "na"}:${built.used}`,
      detail: optionalMissing.length ? `optional tables unavailable: ${optionalMissing.join(", ")}` : undefined,
      missing: optionalMissing.length ? optionalMissing : undefined,
      data: data as unknown as Record<string, unknown>,
    };
  },

  async buildEvents(deps, marketRows, ctx) {
    const skipped: SkipEntry[] = [];
    const events: Array<{ event: EventContext; market: MarketContext }> = [];
    const idx = buildMarketIndex(marketRows);
    if (ctx.status === "ok") (ctx.data as unknown as UfcCtxData).index = idx;

    const all = Object.values(idx.byEvent)
      .sort((a, b) => String(a.commence_time ?? "").localeCompare(String(b.commence_time ?? "")));

    if (ctx.status !== "ok") {
      for (const ev of all) {
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} vs ${ev.home_team}`, reason: "model_context_failed", detail: ctx.detail });
      }
      return { events, skipped, scheduled: all.length };
    }

    const d = ctx.data as unknown as UfcCtxData;
    for (const ev of all) {
      if (!ev.h2hHome && !ev.h2hAway) {
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} vs ${ev.home_team}`, reason: "missing_market", detail: "no h2h captured" });
        continue;
      }
      const claimed = claimById(idx, ev.event_id);
      if (!claimed) {
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} vs ${ev.home_team}`, reason: "duplicate_event", detail: "event already claimed this run" });
        continue;
      }
      /* A rematch is a DIFFERENT event with the same two names. Identity is the
         event_id, so the pair is never used to look anything up — the same two
         fighters meeting twice produce two independent predictions. */
      const rh = resolveName(d.nameIndex, ev.home_team);
      const ra = resolveName(d.nameIndex, ev.away_team);
      if (!rh.ok || !ra.ok || rh.id === ra.id) {
        const detail = [
          !rh.ok ? `${ev.home_team}: ${rh.reason}` : "",
          !ra.ok ? `${ev.away_team}: ${ra.reason}` : "",
          (rh.ok && ra.ok && rh.id === ra.id) ? "both corners resolved to the same fighter" : "",
        ].filter(Boolean).join("; ");
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} vs ${ev.home_team}`, reason: "missing_participant", detail: `unresolved in ufc.fighters: ${detail}` });
        continue;
      }
      events.push({
        event: {
          event_id: ev.event_id,
          sport_key: ev.sport_key || UFC_SPORT_KEY,
          commence_time: ev.commence_time,
          home_team: ev.home_team,
          away_team: ev.away_team,
          extra: { homeId: rh.id, awayId: ra.id, homeHow: rh.how, awayHow: ra.how },
        },
        market: { event: claimed },
      });
    }
    return { events, skipped, scheduled: all.length };
  },

  validateContext(event, ctx): ValidationResult {
    if (ctx.status !== "ok") return { ok: false, reason: "model_context_failed", detail: ctx.detail };
    const d = ctx.data as unknown as UfcCtxData;
    const x = event.extra as any;
    const minBouts = envNum("UFC_MIN_FIGHTER_BOUTS", 3);
    const ha = matchesOf(d.elo, x.homeId);
    const aa = matchesOf(d.elo, x.awayId);
    if (ha < minBouts || aa < minBouts) {
      return {
        ok: false,
        reason: "insufficient_sample",
        detail: `rated bouts: ${event.home_team}=${ha}, ${event.away_team}=${aa} (need >= ${minBouts} each)`,
      };
    }
    return { ok: true };
  },

  async predict(event, market, ctx): Promise<ModelPrediction[]> {
    const d = ctx.data as unknown as UfcCtxData;
    const x = event.extra as any;
    const ev = market.event;

    const { values, missing } = matchupFeatures(d, x.homeId, x.awayId, event.commence_time);
    let pHome = eloProb(values[0], d.elo.params.scale);
    let basis = "fighter_elo";
    const fitVec = FIT_INDEX.map((i) => values[i]);
    if (d.fitted && d.fitted.weights.length === fitVec.length) {
      pHome = applyFit(d.fitted, fitVec);
      basis = "fitted_logistic_matchup";
    } else {
      missing.push("fitted_matchup_weights (run ?calibrate=1)");
    }
    /* The career-average matchup terms are never applied. They are computed and
       stored, and they stay unapplied until a time-sliced stats source exists —
       see UFC_FIT_FEATURES for why. */
    missing.push("as_of_date_career_stats (career averages cannot be applied without leakage)");

    missing.push("short_notice_flag", "weigh_in_result", "camp_status");

    const boutsH = matchesOf(d.elo, x.homeId);
    const boutsA = matchesOf(d.elo, x.awayId);
    const thin = boutsH < 6 || boutsA < 6;
    const quality = thin || !d.career.has(x.homeId) || !d.career.has(x.awayId) ? "LOW" : "MEDIUM";

    const detail: Record<string, unknown> = {
      basis,
      home_elo: +ratingOf(d.elo, x.homeId).toFixed(1),
      away_elo: +ratingOf(d.elo, x.awayId).toFixed(1),
      home_rated_bouts: boutsH,
      away_rated_bouts: boutsA,
      matchup: Object.fromEntries(UFC_FEATURES.map((k, i) => [k, +values[i].toFixed(4)])),
      fit_features: d.fitted ? UFC_FIT_FEATURES : null,
      features_computed_not_applied: UFC_FEATURES.filter((f) =>
        !d.fitted ? f !== "elo_diff" : UFC_FIT_FEATURES.indexOf(f) < 0
      ),
      name_match: { home: x.homeHow, away: x.awayHow },
      history_through: d.historyThrough,
    };

    const out: ModelPrediction[] = [];
    if (ev.h2hHome) out.push({ market: "h2h", selection: ev.home_team, point: null, model_prob: pHome, context_quality: quality, missing_features: missing, detail });
    if (ev.h2hAway) out.push({ market: "h2h", selection: ev.away_team, point: null, model_prob: 1 - pHome, context_quality: quality, missing_features: missing, detail });
    return out;
  },

  telemetryExtra(_rows, ctx) {
    if (ctx.status !== "ok") return { rated_fighters: 0 };
    const d = ctx.data as unknown as UfcCtxData;
    return {
      rated_fighters: d.elo.rating.size,
      bouts_used: d.fightsUsed,
      history_through: d.historyThrough,
      career_stats_rows: d.career.size,
      style_rows: d.style.size,
      derived_rows: d.derived.size,
      parameters: d.fitted ? "calibrated" : "elo_only (no fitted matchup weights stored)",
      unsupported_markets: ["method_of_victory", "fight_goes_distance", "round_props", "totals", "sig_strike_props", "takedown_props"],
    };
  },
};

// ---------------------------------------------------------------------------
// models/nfl.ts
// ---------------------------------------------------------------------------
// ============================================================================
// EdgeDesk : model_predict / models / nfl   —   nfl_game_v1
//
// STATUS ON TODAY'S DATABASE: insufficient_data.
//
// EdgeDesk owns no NFL efficiency table. The model below is complete and
// tested, and it runs the moment `public.nfl_team_features` is populated (the
// migration creates it empty and documents every column). Until then it writes
// nothing and reports exactly which columns are missing. That is deliberate:
// a fabricated 57.3% in the historical record is worse than a gap in it.
//
// MATHEMATICS — WHY NOT A NORMAL DISTRIBUTION.
// NFL scores are not continuous and their margins are not smooth. Points arrive
// in blocks of 7 and 3, which is why 3 and 7 are the key numbers a normal curve
// cannot see: a Normal(mean, sd) fitted to NFL margins puts the same density on
// a 3-point margin as on a 4-point one, and the whole spread market lives in
// that difference.
//
// So scoring is simulated as a COMPOUND COUNT process: touchdowns and field
// goals are drawn as counts and converted to points, which reproduces the
// discreteness and the key-number spikes by construction. Expected points come
// from efficiency against the specific opponent:
//
//   pts_off = league_ppg
//           + (off_epa_play - lg_off_epa) * plays
//           + (opp_def_epa_play - lg_def_epa) * plays
//
// EPA per play is points added per play by definition, so multiplying by plays
// per game and adding the league baseline is a units-correct construction, not
// a fitted mapping.
//
// PUSH HANDLING. NFL ties are real and NFL spread lines are frequently whole
// numbers, so a push is a live outcome. A pushed bet returns the stake, so the
// fair probability of the priced market is P(win) / (P(win) + P(loss)) — the
// push is removed from the denominator, not counted as half a win. (MLB's
// totals keep their v1.2 (over + 0.5*push) treatment untouched; the two sports
// are not being made consistent with each other at the cost of changing the
// frozen baseline.)
// ============================================================================

export const NFL_MODEL_VERSION = "nfl_game_v1";
export const NFL_SPORT_KEY = "americanfootball_nfl";

const NFL_N_SIM = 20000;
/* Home field, in points. A published league-level constant of the same kind as
   MLB's HOME_XR_MULT, reported on every row as an unfitted parameter and
   overridable from the environment. It is NOT derived from the market. */
const HFA_POINTS = () => envNum("NFL_HFA_POINTS", 2.0);
/* Share of a team's points that arrive as touchdowns, used to split expected
   points into TD and FG counts when the features table does not carry the split
   itself. Reported as an unfitted parameter. */
const TD_SHARE = () => envNum("NFL_TD_SHARE", 0.62);
/* variance/mean for scoring-event counts. 1.0 = Poisson. */
const SCORE_DISPERSION = () => envNum("NFL_SCORE_DISPERSION", 1.15);

export const NFL_REQUIRED_COLUMNS = [
  "off_epa_play",
  "def_epa_play",
  "plays_per_game",
];

export const NFL_OPTIONAL_COLUMNS = [
  "off_pass_epa_play", "off_rush_epa_play", "def_pass_epa_play", "def_rush_epa_play",
  "off_success_rate", "def_success_rate", "sack_rate", "sack_rate_allowed",
  "explosive_rate", "explosive_allowed", "points_for_pg", "points_against_pg",
  "td_per_game", "fg_per_game", "qb_status", "rest_days",
];

export interface NflCtxData {
  set: TeamFeatureSet;
  lgOffEpa: number;
  lgDefEpa: number;
  lgPlays: number;
  lgPpg: number;
  index: ReturnType<typeof buildMarketIndex>;
}

const NFL_CONTRACT: DataContractEntry[] = [
  { feature: "offensive EPA per play (opponent-adjusted)", source: "public.nfl_team_features.off_epa_play", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "weekly", historicalDepth: "season", reliability: "not currently ingested", critical: true },
  { feature: "defensive EPA per play (opponent-adjusted)", source: "public.nfl_team_features.def_epa_play", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "weekly", historicalDepth: "season", reliability: "not currently ingested", critical: true },
  { feature: "plays per game / pace", source: "public.nfl_team_features.plays_per_game", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "weekly", historicalDepth: "season", reliability: "not currently ingested", critical: true },
  { feature: "pass / rush EPA split, success rate, explosive rate", source: "public.nfl_team_features (optional columns)", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "weekly", historicalDepth: "season", reliability: "not currently ingested", critical: false },
  { feature: "pressure and sack rate, both directions", source: "public.nfl_team_features (optional columns)", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "weekly", historicalDepth: "season", reliability: "not currently ingested", critical: false },
  { feature: "points scored / allowed per game (degraded fallback)", source: "public.game_stats, only if points_for/points_against/games exist", sourceClass: "NOT_AVAILABLE", updateFrequency: "n/a", historicalDepth: "n/a", reliability: "columns not present today", critical: false },
  { feature: "quarterback status", source: "not ingested — NEVER inferred", sourceClass: "NOT_AVAILABLE", updateFrequency: "n/a", historicalDepth: "n/a", reliability: "n/a", critical: false },
  { feature: "injury report", source: "not ingested — NEVER inferred", sourceClass: "NOT_AVAILABLE", updateFrequency: "n/a", historicalDepth: "n/a", reliability: "n/a", critical: false },
  { feature: "rest days / bye / short week / travel", source: "derivable from public.signals commence_time history", sourceClass: "AVAILABLE_FROM_EXISTING_PROVIDER", updateFrequency: "with capture", historicalDepth: "capture history", reliability: "derived", critical: false },
  { feature: "weather at kickoff", source: "public.venue_weather / api.weather.gov", sourceClass: "AVAILABLE_FROM_EXISTING_PROVIDER", updateFrequency: "hourly", historicalDepth: "n/a", reliability: "NWS", critical: false },
];

/** Expected points for both sides. Pure, so the tests can pin it without a
 *  simulator or a database. */
export function expectedPoints(
  d: NflCtxData,
  homeNorm: string,
  awayNorm: string,
): { home: number; away: number } | null {
  const h = d.set.byTeam.get(homeNorm);
  const a = d.set.byTeam.get(awayNorm);
  if (!h || !a) return null;

  if (d.set.kind === "points_fallback") {
    const hFor = numOr(h, "points_for", null), hAg = numOr(h, "points_against", null), hG = numOr(h, "games", null);
    const aFor = numOr(a, "points_for", null), aAg = numOr(a, "points_against", null), aG = numOr(a, "games", null);
    if (hFor == null || hAg == null || !hG || aFor == null || aAg == null || !aG) return null;
    /* Offence and defence each contribute half the deviation from the league
       baseline — the standard points-for/points-against decomposition. */
    const hOff = hFor / hG, hDef = hAg / hG, aOff = aFor / aG, aDef = aAg / aG;
    const lg = d.lgPpg;
    const home = lg + (hOff - lg) + (aDef - lg) + HFA_POINTS() / 2;
    const away = lg + (aOff - lg) + (hDef - lg) - HFA_POINTS() / 2;
    return { home: Math.max(3, home), away: Math.max(3, away) };
  }

  const hOffEpa = numOr(h, "off_epa_play", null);
  const hDefEpa = numOr(h, "def_epa_play", null);
  const hPlays = numOr(h, "plays_per_game", d.lgPlays) ?? d.lgPlays;
  const aOffEpa = numOr(a, "off_epa_play", null);
  const aDefEpa = numOr(a, "def_epa_play", null);
  const aPlays = numOr(a, "plays_per_game", d.lgPlays) ?? d.lgPlays;
  if (hOffEpa == null || hDefEpa == null || aOffEpa == null || aDefEpa == null) return null;

  /* Plays are shared between the two offences in a game, so each offence gets
     the average of its own pace and the opponent's — a fast offence facing a
     slow one lands in between rather than getting its full season pace. */
  const plays = (hPlays + aPlays) / 2;

  const home = d.lgPpg
    + (hOffEpa - d.lgOffEpa) * plays
    + (aDefEpa - d.lgDefEpa) * plays
    + HFA_POINTS() / 2;
  const away = d.lgPpg
    + (aOffEpa - d.lgOffEpa) * plays
    + (hDefEpa - d.lgDefEpa) * plays
    - HFA_POINTS() / 2;
  return { home: Math.max(3, home), away: Math.max(3, away) };
}

/** Draw one team's score. Touchdown and field-goal counts, not a normal curve —
 *  this is what puts mass on 3, 7, 10, 14, 17 and 21. */
export function drawScore(rng: { next(): number }, expPts: number, tdShare: number, disp: number): number {
  const tdPoints = 6.94; // TD + the conversion actually made, league-typical
  const lamTd = Math.max(0, expPts * tdShare) / tdPoints;
  const lamFg = Math.max(0, expPts * (1 - tdShare)) / 3;
  const td = negBinomial(rng as any, lamTd, disp);
  const fg = negBinomial(rng as any, lamFg, disp);
  let pts = fg * 3;
  for (let i = 0; i < td; i++) {
    // Extra point vs two-point try, at league-typical rates. Keeps 7 dominant
    // while allowing the 6 and 8 that make key numbers imperfect.
    const u = rng.next();
    pts += u < 0.92 ? 7 : u < 0.96 ? 6 : 8;
  }
  return pts;
}

export const NFLModel: SportPredictionModel = {
  sportKey: NFL_SPORT_KEY,
  sportKeyPrefixes: ["americanfootball_nfl"],
  uiLabel: "NFL",
  modelVersion: NFL_MODEL_VERSION,
  supportedMarkets: ["h2h", "spreads", "totals"],
  dataContract: NFL_CONTRACT,

  supportsMarket(market: string): boolean {
    return market === "h2h" || market === "spreads" || market === "totals";
  },

  async loadContext(deps: ModelDeps): Promise<ModelContext> {
    const set = await loadTeamFeatures(deps, {
      contractTable: "nfl_team_features",
      requiredColumns: NFL_REQUIRED_COLUMNS,
      fallbackTable: "game_stats",
      pointsColumns: { scored: "points_for", allowed: "points_against", games: "games" },
    });

    if (set.kind === "none") {
      return {
        status: "insufficient_data",
        missing: set.missingColumns.length ? set.missingColumns : ["nfl_team_features"],
        detail: set.detail ??
          "No NFL team-efficiency source. Populate public.nfl_team_features (see supabase/migrations) with at least off_epa_play, def_epa_play and plays_per_game.",
      };
    }

    const lgOffEpa = leagueMean(set, "off_epa_play") ?? 0;
    const lgDefEpa = leagueMean(set, "def_epa_play") ?? 0;
    const lgPlays = leagueMean(set, "plays_per_game") ?? 63;
    const lgPpg = leagueMean(set, "points_for_pg")
      ?? (set.kind === "points_fallback" ? pointsFallbackLeaguePpg(set) : null)
      ?? envNum("NFL_LEAGUE_PPG", 22.5);

    const data: NflCtxData = { set, lgOffEpa, lgDefEpa, lgPlays, lgPpg, index: buildMarketIndex([]) };
    return {
      status: "ok",
      dataAsOf: set.dataAsOf,
      featureSnapshotId: `${NFL_MODEL_VERSION}:${set.table}:${set.dataAsOf ?? "na"}:${set.byTeam.size}`,
      detail: set.detail,
      data: data as unknown as Record<string, unknown>,
    };
  },

  async buildEvents(deps, marketRows, ctx) {
    const skipped: SkipEntry[] = [];
    const events: Array<{ event: EventContext; market: MarketContext }> = [];
    const idx = buildMarketIndex(marketRows);
    if (ctx.status === "ok") (ctx.data as unknown as NflCtxData).index = idx;

    const all = Object.values(idx.byEvent)
      .sort((a, b) => String(a.commence_time ?? "").localeCompare(String(b.commence_time ?? "")));

    if (ctx.status !== "ok") {
      for (const ev of all) {
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} @ ${ev.home_team}`, reason: "model_context_failed", detail: ctx.detail });
      }
      return { events, skipped, scheduled: all.length };
    }

    const d = ctx.data as unknown as NflCtxData;
    for (const ev of all) {
      const claimed = claimById(idx, ev.event_id);
      if (!claimed) {
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} @ ${ev.home_team}`, reason: "duplicate_event" });
        continue;
      }
      const hk = nrm(ev.home_team), ak = nrm(ev.away_team);
      if (!d.set.byTeam.has(hk) || !d.set.byTeam.has(ak)) {
        const miss = [!d.set.byTeam.has(hk) ? ev.home_team : "", !d.set.byTeam.has(ak) ? ev.away_team : ""].filter(Boolean).join(", ");
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} @ ${ev.home_team}`, reason: "missing_team_stats", detail: `not in ${d.set.table}: ${miss}` });
        continue;
      }
      events.push({
        event: {
          event_id: ev.event_id,
          sport_key: ev.sport_key || NFL_SPORT_KEY,
          commence_time: ev.commence_time,
          home_team: ev.home_team,
          away_team: ev.away_team,
          extra: { hk, ak },
        },
        market: { event: claimed },
      });
    }
    return { events, skipped, scheduled: all.length };
  },

  validateContext(event, ctx): ValidationResult {
    if (ctx.status !== "ok") return { ok: false, reason: "model_context_failed", detail: ctx.detail };
    const d = ctx.data as unknown as NflCtxData;
    const x = event.extra as any;
    if (!expectedPoints(d, x.hk, x.ak)) {
      return { ok: false, reason: "missing_team_stats", detail: "expected points could not be computed from the loaded columns" };
    }
    return { ok: true };
  },

  async predict(event, market, ctx, deps): Promise<ModelPrediction[]> {
    const d = ctx.data as unknown as NflCtxData;
    const x = event.extra as any;
    const ev = market.event;
    const xp = expectedPoints(d, x.hk, x.ak);
    if (!xp) return [];

    const totalLine = ev.mainTotal?.point ?? null;
    const spreadLine = ev.mainSpread?.point ?? null; // home handicap
    const tdShare = TD_SHARE(), disp = SCORE_DISPERSION();

    let hWin = 0, aWin = 0, tie = 0;
    let over = 0, under = 0, totalPush = 0;
    let homeCover = 0, awayCover = 0, spreadPush = 0;
    let sumTotal = 0, sumMargin = 0;

    for (let i = 0; i < NFL_N_SIM; i++) {
      const hs = drawScore(deps.rng, xp.home, tdShare, disp);
      const as = drawScore(deps.rng, xp.away, tdShare, disp);
      if (hs > as) hWin++; else if (as > hs) aWin++; else tie++;
      const t = hs + as, m = hs - as;
      sumTotal += t; sumMargin += m;
      if (totalLine != null) {
        if (t > totalLine) over++; else if (t < totalLine) under++; else totalPush++;
      }
      if (spreadLine != null) {
        const adj = m + spreadLine; // home covers when margin + handicap > 0
        if (adj > 0) homeCover++; else if (adj < 0) awayCover++; else spreadPush++;
      }
    }

    /* Push-excluded normalisation. A pushed bet returns the stake, so the fair
       probability of the priced outcome conditions on the bet resolving. */
    const norm = (win: number, loss: number): number | null => {
      const dz = win + loss;
      return dz > 0 ? win / dz : null;
    };

    const pHome = norm(hWin, aWin);
    const pAway = pHome != null ? 1 - pHome : null;
    const pOver = totalLine != null ? norm(over, under) : null;
    const pUnder = pOver != null ? 1 - pOver : null;
    const pHomeSpread = spreadLine != null ? norm(homeCover, awayCover) : null;
    const pAwaySpread = pHomeSpread != null ? 1 - pHomeSpread : null;

    const missing: string[] = ["qb_status", "injury_report", "weather", "rest_travel"];
    if (d.set.kind === "points_fallback") missing.push("opponent_adjusted_efficiency", "pass_rush_split", "pressure_rate");
    else {
      for (const c of ["off_pass_epa_play", "off_rush_epa_play", "sack_rate", "explosive_rate"]) {
        if (d.set.columns.indexOf(c) < 0) missing.push(c);
      }
    }
    missing.push("home_field_advantage (unfitted parameter)");
    const quality = d.set.kind === "points_fallback" ? "LOW" : missing.length > 6 ? "LOW" : "MEDIUM";

    const detail = {
      basis: d.set.kind === "points_fallback" ? "points_differential" : "epa_efficiency",
      source_table: d.set.table,
      expected_home_points: +xp.home.toFixed(2),
      expected_away_points: +xp.away.toFixed(2),
      sim_mean_total: +(sumTotal / NFL_N_SIM).toFixed(2),
      sim_mean_margin: +(sumMargin / NFL_N_SIM).toFixed(2),
      p_tie: +(tie / NFL_N_SIM).toFixed(4),
      total_push_rate: totalLine != null ? +(totalPush / NFL_N_SIM).toFixed(4) : null,
      spread_push_rate: spreadLine != null ? +(spreadPush / NFL_N_SIM).toFixed(4) : null,
      n_sim: NFL_N_SIM,
      hfa_points: HFA_POINTS(),
      td_share: tdShare,
      score_dispersion: disp,
    };

    const out: ModelPrediction[] = [];
    const add = (m: string, sel: string, pt: number | null, p: number | null) => {
      if (p == null || !Number.isFinite(p)) return;
      out.push({ market: m, selection: sel, point: pt, model_prob: p, context_quality: quality, missing_features: missing, detail });
    };
    if (ev.h2hHome) add("h2h", ev.home_team, null, pHome);
    if (ev.h2hAway) add("h2h", ev.away_team, null, pAway);
    if (totalLine != null && ev.mainTotal?.over) add("totals", "Over", totalLine, pOver);
    if (totalLine != null && ev.mainTotal?.under) add("totals", "Under", totalLine, pUnder);
    if (spreadLine != null && ev.mainSpread?.home) add("spreads", ev.home_team, spreadLine, pHomeSpread);
    if (spreadLine != null && ev.mainSpread?.away) add("spreads", ev.away_team, -spreadLine, pAwaySpread);
    return out;
  },

  telemetryExtra(_rows, ctx) {
    if (ctx.status !== "ok") return { source: "unavailable" };
    const d = ctx.data as unknown as NflCtxData;
    return {
      source_table: d.set.table,
      source_kind: d.set.kind,
      teams_loaded: d.set.byTeam.size,
      league_baselines: {
        off_epa_play: +d.lgOffEpa.toFixed(4),
        def_epa_play: +d.lgDefEpa.toFixed(4),
        plays_per_game: +d.lgPlays.toFixed(2),
        points_per_game: +d.lgPpg.toFixed(2),
      },
      unfitted_parameters: { hfa_points: HFA_POINTS(), td_share: TD_SHARE(), score_dispersion: SCORE_DISPERSION() },
    };
  },
};

function pointsFallbackLeaguePpg(set: TeamFeatureSet): number | null {
  let s = 0, n = 0;
  for (const [, row] of set.byTeam) {
    const f = numOr(row, "points_for", null), g = numOr(row, "games", null);
    if (f != null && g) { s += f / g; n++; }
  }
  return n ? s / n : null;
}

// ---------------------------------------------------------------------------
// models/wnba.ts
// ---------------------------------------------------------------------------
// ============================================================================
// EdgeDesk : model_predict / models / wnba   —   wnba_game_v1
//
// STATUS ON TODAY'S DATABASE: insufficient_data.
//
// EdgeDesk owns no WNBA team-rating table. The model is complete and tested and
// runs as soon as `public.wnba_team_features` is populated; until then it
// writes nothing and says which columns are missing.
//
// NOT NBA WITH A DIFFERENT KEY. Every league constant here — pace, league
// points per possession, home court — is computed from the WNBA rows that are
// actually loaded, never carried over from an NBA prior. The app's own sport
// contract already warns that WNBA thresholds must not be imported from the
// NBA; this module has no NBA numbers in it to import.
//
// MATHEMATICS. Possession-based, because basketball is a possession game and
// the number of possessions is what converts an efficiency edge into points.
//
//   possessions = pace_home * pace_away / league_pace
//   ppp_home    = (off_rating_home * def_rating_away / league_rating) / 100
//
// Both are the standard efficiency-interaction forms: a fast team meeting a
// slow one lands between them, and an elite offence facing an elite defence is
// pulled toward the league mean rather than simply averaged.
//
// Scoring is then simulated PER POSSESSION from a {0, 2, 3} categorical whose
// three-point share comes from the team's own shooting profile when the column
// exists. That matters for the same reason NFL's TD/FG counts matter: it puts
// real mass on even margins and on the totals bucket boundaries, which a
// continuous normal approximation smears away. With ~80 possessions a side the
// margin ends up near-normal anyway — that is a RESULT of the simulation, not
// an assumption fed into it.
//
// PUSH HANDLING. Whole-number spreads and totals push; the fair probability of
// the priced outcome removes pushes from the denominator.
// ============================================================================

export const WNBA_MODEL_VERSION = "wnba_game_v1";
export const WNBA_SPORT_KEY = "basketball_wnba";

const WNBA_N_SIM = 20000;
/** Home court, in points. Unfitted parameter, reported on every row. */
const HCA_POINTS = () => envNum("WNBA_HCA_POINTS", 2.0);

export const WNBA_REQUIRED_COLUMNS = ["off_rating", "def_rating", "pace"];
export const WNBA_OPTIONAL_COLUMNS = [
  "efg_pct", "opp_efg_pct", "tov_pct", "opp_tov_pct", "orb_pct", "drb_pct",
  "ft_rate", "opp_ft_rate", "three_rate", "rest_days",
];

export interface WnbaCtxData {
  set: TeamFeatureSet;
  lgRating: number;
  lgPace: number;
  lgThreeRate: number;
  index: ReturnType<typeof buildMarketIndex>;
}

const WNBA_CONTRACT: DataContractEntry[] = [
  { feature: "offensive rating (points per 100 possessions)", source: "public.wnba_team_features.off_rating", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "daily", historicalDepth: "season", reliability: "not currently ingested", critical: true },
  { feature: "defensive rating", source: "public.wnba_team_features.def_rating", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "daily", historicalDepth: "season", reliability: "not currently ingested", critical: true },
  { feature: "pace (possessions per game)", source: "public.wnba_team_features.pace", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "daily", historicalDepth: "season", reliability: "not currently ingested", critical: true },
  { feature: "four factors (eFG%, TOV%, ORB%, FT rate) both directions", source: "public.wnba_team_features (optional columns)", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "daily", historicalDepth: "season", reliability: "not currently ingested", critical: false },
  { feature: "three-point attempt rate", source: "public.wnba_team_features.three_rate", sourceClass: "REQUIRES_NEW_PROVIDER", updateFrequency: "daily", historicalDepth: "season", reliability: "used to shape the per-possession draw", critical: false },
  { feature: "points scored / allowed per game (degraded fallback)", source: "public.game_stats, only if points_for/points_against/games exist", sourceClass: "NOT_AVAILABLE", updateFrequency: "n/a", historicalDepth: "n/a", reliability: "columns not present today", critical: false },
  { feature: "player availability / injury / rest", source: "not ingested — NEVER inferred", sourceClass: "NOT_AVAILABLE", updateFrequency: "n/a", historicalDepth: "n/a", reliability: "n/a", critical: false },
  { feature: "minutes, usage, lineup effects", source: "public.stats_players holds leaderboard lines, not minutes or lineups", sourceClass: "NOT_AVAILABLE", updateFrequency: "n/a", historicalDepth: "n/a", reliability: "n/a", critical: false },
  { feature: "back-to-backs / rest days / travel", source: "derivable from public.signals commence_time history", sourceClass: "AVAILABLE_FROM_EXISTING_PROVIDER", updateFrequency: "with capture", historicalDepth: "capture history", reliability: "derived", critical: false },
];

export interface GameShape {
  possessions: number;
  pppHome: number;
  pppAway: number;
  threeHome: number;
  threeAway: number;
}

/** Possessions and per-possession efficiency for one matchup. Pure. */
export function gameShape(d: WnbaCtxData, homeNorm: string, awayNorm: string): GameShape | null {
  const h = d.set.byTeam.get(homeNorm);
  const a = d.set.byTeam.get(awayNorm);
  if (!h || !a) return null;

  if (d.set.kind === "points_fallback") {
    const hFor = numOr(h, "points_for", null), hAg = numOr(h, "points_against", null), hG = numOr(h, "games", null);
    const aFor = numOr(a, "points_for", null), aAg = numOr(a, "points_against", null), aG = numOr(a, "games", null);
    if (hFor == null || hAg == null || !hG || aFor == null || aAg == null || !aG) return null;
    const poss = d.lgPace;
    const lgPts = (hFor / hG + hAg / hG + aFor / aG + aAg / aG) / 4;
    const homePts = lgPts + ((hFor / hG - lgPts) + (aAg / aG - lgPts)) + HCA_POINTS() / 2;
    const awayPts = lgPts + ((aFor / aG - lgPts) + (hAg / hG - lgPts)) - HCA_POINTS() / 2;
    return {
      possessions: poss,
      pppHome: Math.max(0.5, homePts / poss),
      pppAway: Math.max(0.5, awayPts / poss),
      threeHome: d.lgThreeRate,
      threeAway: d.lgThreeRate,
    };
  }

  const hOff = numOr(h, "off_rating", null), hDef = numOr(h, "def_rating", null), hPace = numOr(h, "pace", null);
  const aOff = numOr(a, "off_rating", null), aDef = numOr(a, "def_rating", null), aPace = numOr(a, "pace", null);
  if (hOff == null || hDef == null || !hPace || aOff == null || aDef == null || !aPace) return null;

  const possessions = (hPace * aPace) / d.lgPace;
  // Efficiency interaction: own offence against that specific defence,
  // renormalised by the league so the scale stays points per 100.
  const homeRating = (hOff * aDef) / d.lgRating;
  const awayRating = (aOff * hDef) / d.lgRating;
  const hcaPerPoss = HCA_POINTS() / 2 / possessions;

  return {
    possessions,
    pppHome: Math.max(0.5, homeRating / 100 + hcaPerPoss),
    pppAway: Math.max(0.5, awayRating / 100 - hcaPerPoss),
    threeHome: numOr(h, "three_rate", d.lgThreeRate) ?? d.lgThreeRate,
    threeAway: numOr(a, "three_rate", d.lgThreeRate) ?? d.lgThreeRate,
  };
}

/**
 * Score one team over `poss` possessions.
 *
 * Each possession returns 0, 2 or 3 points. The three-point share is the team's
 * own attempt rate; given that share and the required mean points per
 * possession, the scoring probability is determined — no free parameter is
 * chosen. Free throws are folded into the 2-point outcome rather than modelled
 * separately, which the detail block states rather than hiding.
 */
export function drawTeamPoints(rng: { next(): number }, poss: number, ppp: number, threeShare: number): number {
  const share3 = Math.min(0.9, Math.max(0, threeShare));
  // E[pts|score] = 3*share3 + 2*(1-share3); pScore = ppp / E[pts|score]
  const perScore = 3 * share3 + 2 * (1 - share3);
  const pScore = Math.min(0.95, Math.max(0.05, ppp / perScore));
  const n = Math.max(1, Math.round(poss));
  let pts = 0;
  const table: Array<[number, number]> = [
    [0, 1 - pScore],
    [3, pScore * share3],
    [2, pScore * (1 - share3)],
  ];
  for (let i = 0; i < n; i++) pts += categorical(rng as any, table);
  return pts;
}

export const WNBAModel: SportPredictionModel = {
  sportKey: WNBA_SPORT_KEY,
  sportKeyPrefixes: ["basketball_wnba"],
  uiLabel: "WNBA",
  modelVersion: WNBA_MODEL_VERSION,
  supportedMarkets: ["h2h", "spreads", "totals"],
  dataContract: WNBA_CONTRACT,

  supportsMarket(market: string): boolean {
    return market === "h2h" || market === "spreads" || market === "totals";
  },

  async loadContext(deps: ModelDeps): Promise<ModelContext> {
    const set = await loadTeamFeatures(deps, {
      contractTable: "wnba_team_features",
      requiredColumns: WNBA_REQUIRED_COLUMNS,
      fallbackTable: "game_stats",
      pointsColumns: { scored: "points_for", allowed: "points_against", games: "games" },
    });

    if (set.kind === "none") {
      return {
        status: "insufficient_data",
        missing: set.missingColumns.length ? set.missingColumns : ["wnba_team_features"],
        detail: set.detail ??
          "No WNBA team-rating source. Populate public.wnba_team_features (see supabase/migrations) with at least off_rating, def_rating and pace.",
      };
    }

    /* Every league baseline is computed from the WNBA rows that were loaded.
       There is no NBA constant anywhere in this file to fall back on. */
    const lgOff = leagueMean(set, "off_rating");
    const lgDef = leagueMean(set, "def_rating");
    const lgRating = lgOff != null && lgDef != null ? (lgOff + lgDef) / 2 : lgOff ?? lgDef ?? envNum("WNBA_LEAGUE_RATING", 100);
    const lgPace = leagueMean(set, "pace") ?? envNum("WNBA_LEAGUE_PACE", 80);
    const lgThreeRate = leagueMean(set, "three_rate") ?? envNum("WNBA_LEAGUE_THREE_RATE", 0.3);

    const data: WnbaCtxData = { set, lgRating, lgPace, lgThreeRate, index: buildMarketIndex([]) };
    return {
      status: "ok",
      dataAsOf: set.dataAsOf,
      featureSnapshotId: `${WNBA_MODEL_VERSION}:${set.table}:${set.dataAsOf ?? "na"}:${set.byTeam.size}`,
      detail: set.detail,
      data: data as unknown as Record<string, unknown>,
    };
  },

  async buildEvents(deps, marketRows, ctx) {
    const skipped: SkipEntry[] = [];
    const events: Array<{ event: EventContext; market: MarketContext }> = [];
    const idx = buildMarketIndex(marketRows);
    if (ctx.status === "ok") (ctx.data as unknown as WnbaCtxData).index = idx;

    const all = Object.values(idx.byEvent)
      .sort((a, b) => String(a.commence_time ?? "").localeCompare(String(b.commence_time ?? "")));

    if (ctx.status !== "ok") {
      for (const ev of all) {
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} @ ${ev.home_team}`, reason: "model_context_failed", detail: ctx.detail });
      }
      return { events, skipped, scheduled: all.length };
    }

    const d = ctx.data as unknown as WnbaCtxData;
    for (const ev of all) {
      const claimed = claimById(idx, ev.event_id);
      if (!claimed) {
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} @ ${ev.home_team}`, reason: "duplicate_event" });
        continue;
      }
      const hk = nrm(ev.home_team), ak = nrm(ev.away_team);
      if (!d.set.byTeam.has(hk) || !d.set.byTeam.has(ak)) {
        const miss = [!d.set.byTeam.has(hk) ? ev.home_team : "", !d.set.byTeam.has(ak) ? ev.away_team : ""].filter(Boolean).join(", ");
        skipped.push({ event_id: ev.event_id, label: `${ev.away_team} @ ${ev.home_team}`, reason: "missing_team_stats", detail: `not in ${d.set.table}: ${miss}` });
        continue;
      }
      events.push({
        event: {
          event_id: ev.event_id,
          sport_key: ev.sport_key || WNBA_SPORT_KEY,
          commence_time: ev.commence_time,
          home_team: ev.home_team,
          away_team: ev.away_team,
          extra: { hk, ak },
        },
        market: { event: claimed },
      });
    }
    return { events, skipped, scheduled: all.length };
  },

  validateContext(event, ctx): ValidationResult {
    if (ctx.status !== "ok") return { ok: false, reason: "model_context_failed", detail: ctx.detail };
    const d = ctx.data as unknown as WnbaCtxData;
    const x = event.extra as any;
    if (!gameShape(d, x.hk, x.ak)) {
      return { ok: false, reason: "missing_team_stats", detail: "possessions/efficiency could not be computed from the loaded columns" };
    }
    return { ok: true };
  },

  async predict(event, market, ctx, deps): Promise<ModelPrediction[]> {
    const d = ctx.data as unknown as WnbaCtxData;
    const x = event.extra as any;
    const ev = market.event;
    const shape = gameShape(d, x.hk, x.ak);
    if (!shape) return [];

    const totalLine = ev.mainTotal?.point ?? null;
    const spreadLine = ev.mainSpread?.point ?? null;

    let hWin = 0, aWin = 0;
    let over = 0, under = 0, totalPush = 0;
    let homeCover = 0, awayCover = 0, spreadPush = 0;
    let sumTotal = 0, sumMargin = 0;

    for (let i = 0; i < WNBA_N_SIM; i++) {
      const hs = drawTeamPoints(deps.rng, shape.possessions, shape.pppHome, shape.threeHome);
      const as = drawTeamPoints(deps.rng, shape.possessions, shape.pppAway, shape.threeAway);
      /* Basketball has no ties: a level score goes to overtime. Rather than
         simulating an extra period, a tie is resolved by a fair coin, which is
         what an even-strength overtime is to within far less than the noise on
         everything else here. It is stated in the detail block. */
      if (hs > as) hWin++;
      else if (as > hs) aWin++;
      else if (deps.rng.next() < 0.5) hWin++;
      else aWin++;

      const t = hs + as, m = hs - as;
      sumTotal += t; sumMargin += m;
      if (totalLine != null) {
        if (t > totalLine) over++; else if (t < totalLine) under++; else totalPush++;
      }
      if (spreadLine != null) {
        const adj = m + spreadLine;
        if (adj > 0) homeCover++; else if (adj < 0) awayCover++; else spreadPush++;
      }
    }

    const norm = (win: number, loss: number): number | null => {
      const dz = win + loss;
      return dz > 0 ? win / dz : null;
    };
    const pHome = norm(hWin, aWin);
    const pAway = pHome != null ? 1 - pHome : null;
    const pOver = totalLine != null ? norm(over, under) : null;
    const pUnder = pOver != null ? 1 - pOver : null;
    const pHomeSpread = spreadLine != null ? norm(homeCover, awayCover) : null;
    const pAwaySpread = pHomeSpread != null ? 1 - pHomeSpread : null;

    const missing: string[] = ["player_availability", "injury_report", "minutes_usage", "lineup_effects", "rest_back_to_back"];
    if (d.set.kind === "points_fallback") missing.push("off_rating", "def_rating", "pace", "four_factors");
    else {
      for (const c of ["efg_pct", "tov_pct", "orb_pct", "ft_rate", "three_rate"]) {
        if (d.set.columns.indexOf(c) < 0) missing.push(c);
      }
    }
    missing.push("home_court_advantage (unfitted parameter)");
    const quality = d.set.kind === "points_fallback" ? "LOW" : "MEDIUM";

    const detail = {
      basis: d.set.kind === "points_fallback" ? "points_differential" : "possession_efficiency",
      source_table: d.set.table,
      possessions: +shape.possessions.toFixed(2),
      ppp_home: +shape.pppHome.toFixed(4),
      ppp_away: +shape.pppAway.toFixed(4),
      expected_home_points: +(shape.pppHome * shape.possessions).toFixed(2),
      expected_away_points: +(shape.pppAway * shape.possessions).toFixed(2),
      sim_mean_total: +(sumTotal / WNBA_N_SIM).toFixed(2),
      sim_mean_margin: +(sumMargin / WNBA_N_SIM).toFixed(2),
      total_push_rate: totalLine != null ? +(totalPush / WNBA_N_SIM).toFixed(4) : null,
      spread_push_rate: spreadLine != null ? +(spreadPush / WNBA_N_SIM).toFixed(4) : null,
      n_sim: WNBA_N_SIM,
      hca_points: HCA_POINTS(),
      notes: "free throws folded into the 2-point possession outcome; ties resolved as a fair coin in lieu of an overtime model",
    };

    const out: ModelPrediction[] = [];
    const add = (m: string, sel: string, pt: number | null, p: number | null) => {
      if (p == null || !Number.isFinite(p)) return;
      out.push({ market: m, selection: sel, point: pt, model_prob: p, context_quality: quality, missing_features: missing, detail });
    };
    if (ev.h2hHome) add("h2h", ev.home_team, null, pHome);
    if (ev.h2hAway) add("h2h", ev.away_team, null, pAway);
    if (totalLine != null && ev.mainTotal?.over) add("totals", "Over", totalLine, pOver);
    if (totalLine != null && ev.mainTotal?.under) add("totals", "Under", totalLine, pUnder);
    if (spreadLine != null && ev.mainSpread?.home) add("spreads", ev.home_team, spreadLine, pHomeSpread);
    if (spreadLine != null && ev.mainSpread?.away) add("spreads", ev.away_team, -spreadLine, pAwaySpread);
    return out;
  },

  telemetryExtra(_rows, ctx) {
    if (ctx.status !== "ok") return { source: "unavailable" };
    const d = ctx.data as unknown as WnbaCtxData;
    return {
      source_table: d.set.table,
      source_kind: d.set.kind,
      teams_loaded: d.set.byTeam.size,
      league_baselines: {
        rating: +d.lgRating.toFixed(2),
        pace: +d.lgPace.toFixed(2),
        three_rate: +d.lgThreeRate.toFixed(3),
      },
      unfitted_parameters: { hca_points: HCA_POINTS() },
      note: "every baseline above is computed from the loaded WNBA rows; no NBA prior is used",
    };
  },
};

// ---------------------------------------------------------------------------
// core/registry.ts
// ---------------------------------------------------------------------------
// ============================================================================
// EdgeDesk : model_predict / core / registry
//
// One place that knows which model owns which sport. The frontend's sport
// taxonomy and the backend's must not be allowed to drift, so the labels here
// are the labels app.html already uses — evSportLabel() maps tennis_atp_* to
// "ATP", americanfootball_nfl* to "NFL", and prettySport() maps
// mma_mixed_martial_arts to "MMA" — and `describe()` publishes the whole thing
// so the UI can read it instead of hardcoding a second copy.
//
// ROUTING IS BY PREFIX, NOT BY EQUALITY. The Odds API names tennis per event
// (tennis_atp_wimbledon, tennis_wta_cincinnati) and football per phase
// (americanfootball_nfl_preseason). Matching on equality would silently drop
// every tennis event and every preseason game.
// ============================================================================

export const MODEL_REGISTRY: Record<string, SportPredictionModel> = {
  baseball_mlb: MLBModel,
  tennis_atp: ATPModel,
  tennis_wta: WTAModel,
  mma_mixed_martial_arts: UFCModel,
  americanfootball_nfl: NFLModel,
  basketball_wnba: WNBAModel,
};

export const REGISTERED_SPORTS = Object.keys(MODEL_REGISTRY);

/**
 * Which model owns a captured sport_key.
 *
 * Longest prefix wins, so a future `tennis_atp_challenger` model could be
 * registered alongside `tennis_atp` without the generic one shadowing it.
 */
export function resolveModel(sportKey: string): SportPredictionModel | null {
  const k = String(sportKey || "").toLowerCase();
  if (!k) return null;
  let best: SportPredictionModel | null = null;
  let bestLen = -1;
  for (const key of REGISTERED_SPORTS) {
    const m = MODEL_REGISTRY[key];
    for (const p of m.sportKeyPrefixes) {
      if (k.indexOf(p) === 0 && p.length > bestLen) {
        best = m;
        bestLen = p.length;
      }
    }
  }
  return best;
}

/** The UI label EdgeDesk already shows for a captured sport_key. */
export function uiLabelFor(sportKey: string): string | null {
  return resolveModel(sportKey)?.uiLabel ?? null;
}

/** Resolve a `?sport=` filter. Accepts a registry key, any captured sport_key,
 *  or the UI label (MLB / ATP / WTA / MMA / NFL / WNBA), case-insensitively. */
export function resolveFilter(arg: string): SportPredictionModel | null {
  const raw = String(arg || "").trim();
  if (!raw) return null;
  const direct = MODEL_REGISTRY[raw.toLowerCase()];
  if (direct) return direct;
  const byPrefix = resolveModel(raw);
  if (byPrefix) return byPrefix;
  const label = raw.toUpperCase();
  for (const key of REGISTERED_SPORTS) {
    if (MODEL_REGISTRY[key].uiLabel.toUpperCase() === label) return MODEL_REGISTRY[key];
  }
  return null;
}

/** Machine-readable description of the whole layer. Served from `?registry=1`
 *  so the frontend can render the sport selector and the per-sport "what does
 *  this model need" panel without a second hardcoded list. */
export function describe() {
  return REGISTERED_SPORTS.map((key) => {
    const m = MODEL_REGISTRY[key];
    return {
      sport_key: key,
      sport_key_prefixes: m.sportKeyPrefixes,
      ui_label: m.uiLabel,
      model_version: m.modelVersion,
      supported_markets: m.supportedMarkets,
      required_data: m.dataContract.filter((c) => c.critical).map((c) => c.source),
      data_contract: m.dataContract,
    };
  });
}

// ---------------------------------------------------------------------------
// core/runner.ts
// ---------------------------------------------------------------------------
// ============================================================================
// EdgeDesk : model_predict / core / runner
//
// The shared pipeline. Every sport goes through exactly these steps and no
// sport is allowed its own path through them:
//
//     signals read -> market index -> context load -> event assembly
//         -> validate -> predict -> row build -> dedupe -> write -> telemetry
//
// A failure inside one sport is contained to that sport. A bad tennis schema
// must not cost the MLB slate its predictions, so each model runs inside its
// own try and reports `status: error` with its message while the others carry
// on. The response is the audit record for the run: what was scheduled, what
// was predicted, what was skipped and why, and which captured events nobody
// claimed.
// ============================================================================

/**
 * How far ahead of `now` each sport's captured market is read.
 *
 * MLB keeps v1.2's window exactly (-3h to +30h) because that window is part of
 * the frozen baseline. The others are set to the cadence of the sport: a
 * weekly league needs days of horizon or the slate is invisible, a daily one
 * does not.
 */
export function windowFor(registryKey: string): { backHours: number; aheadHours: number } {
  switch (registryKey) {
    case "baseball_mlb":
      return { backHours: envNum("MODEL_WINDOW_BACK_H", 3), aheadHours: envNum("MLB_WINDOW_AHEAD_H", 30) };
    case "americanfootball_nfl":
      return { backHours: envNum("MODEL_WINDOW_BACK_H", 3), aheadHours: envNum("NFL_WINDOW_AHEAD_H", 192) };
    case "mma_mixed_martial_arts":
      return { backHours: envNum("MODEL_WINDOW_BACK_H", 3), aheadHours: envNum("UFC_WINDOW_AHEAD_H", 192) };
    case "tennis_atp":
    case "tennis_wta":
      return { backHours: envNum("MODEL_WINDOW_BACK_H", 3), aheadHours: envNum("TENNIS_WINDOW_AHEAD_H", 48) };
    case "basketball_wnba":
      return { backHours: envNum("MODEL_WINDOW_BACK_H", 3), aheadHours: envNum("WNBA_WINDOW_AHEAD_H", 36) };
    default:
      return { backHours: 3, aheadHours: 36 };
  }
}

async function readSignals(
  deps: ModelDeps,
  model: SportPredictionModel,
  registryKey: string,
): Promise<SignalRow[]> {
  const w = windowFor(registryKey);
  const lo = new Date(deps.now.getTime() - w.backHours * 3600e3).toISOString();
  const hi = new Date(deps.now.getTime() + w.aheadHours * 3600e3).toISOString();
  const out: SignalRow[] = [];
  const seen = new Set<string>();
  for (const prefix of model.sportKeyPrefixes) {
    /* `like.<prefix>*` catches tennis_atp_wimbledon and
       americanfootball_nfl_preseason alongside the bare key. */
    const filter = `sport_key=like.${encodeURIComponent(prefix)}*`;
    const PAGE = 1000;
    for (let p = 0; p < 8; p++) {
      const rows = await deps.sbGet(
        `signals?select=${SIGNAL_SELECT}&${filter}&commence_time=gte.${lo}&commence_time=lte.${hi}` +
        `&order=commence_time.asc,event_id.asc&limit=${PAGE}&offset=${p * PAGE}`,
      );
      if (!rows || !rows.length) break;
      for (const r of rows) {
        const k = `${r.event_id}|${r.market}|${r.selection}|${r.point}`;
        if (seen.has(k)) continue;
        seen.add(k);
        out.push(r as SignalRow);
      }
      if (rows.length < PAGE) break;
    }
  }
  return out;
}

export interface SportRunResult {
  telemetry: SportTelemetry;
  rows: PredictionRow[];
  samples: PredictionRow[];
}

export async function runSport(
  deps: ModelDeps,
  registryKey: string,
  model: SportPredictionModel,
): Promise<SportRunResult> {
  const telemetry: SportTelemetry = {
    model_version: model.modelVersion,
    ui_label: model.uiLabel,
    status: "ok",
    scheduled: 0,
    eligible: 0,
    predicted: 0,
    skipped: [],
    rows_built: 0,
    rows_written: 0,
    market_events: 0,
    matched_events: 0,
    unmatched_events: [],
    data_quality: { status: "ok" },
  };

  const marketRows = await readSignals(deps, model, registryKey);
  /* Indexed once here purely to count and to report unclaimed events. Each
     model rebuilds its own index inside buildEvents() from the same rows, so
     the claim state the telemetry reads is the model's, not a copy. */
  const marketEvents = eventsInStartOrder(buildMarketIndex(marketRows));
  telemetry.market_events = marketEvents.length;

  const ctx: ModelContext = await model.loadContext(deps, marketRows);
  telemetry.data_quality = {
    status: ctx.status,
    missing: ctx.missing,
    detail: ctx.detail,
    data_as_of: ctx.dataAsOf ?? null,
    feature_snapshot_id: ctx.featureSnapshotId,
    contract: model.dataContract,
  };

  if (ctx.status !== "ok") {
    telemetry.status = ctx.status;
    /* An unusable context is not an excuse to say nothing about the slate. Every
       captured event is still reported as skipped, with the reason, so the run
       shows what would have been predicted had the data been there. */
    telemetry.scheduled = marketEvents.length;
    telemetry.skipped = marketEvents.slice(0, 50).map((e) => ({
      event_id: e.event_id,
      label: `${e.away_team} @ ${e.home_team}`,
      reason: "model_context_failed" as const,
      detail: ctx.detail,
    }));
    telemetry.unmatched_events = marketEvents.slice(0, 10).map((e) => ({
      event_id: e.event_id,
      game: `${e.away_team} @ ${e.home_team}`,
      commence_time: e.commence_time,
    }));
    if (model.telemetryExtra) telemetry.extra = model.telemetryExtra([], ctx);
    return { telemetry, rows: [], samples: [] };
  }

  const assembled = await model.buildEvents(deps, marketRows, ctx);
  telemetry.scheduled = assembled.scheduled;
  telemetry.skipped.push(...assembled.skipped);
  telemetry.eligible = assembled.events.length;

  const rows: PredictionRow[] = [];
  for (const { event, market } of assembled.events) {
    const v = model.validateContext(event, ctx);
    if (!v.ok) {
      telemetry.skipped.push({
        event_id: event.event_id,
        label: `${event.away_team} @ ${event.home_team}`,
        reason: v.reason ?? "model_context_failed",
        detail: v.detail,
      });
      continue;
    }

    let preds;
    try {
      preds = await model.predict(event, market, ctx, deps);
    } catch (e) {
      telemetry.skipped.push({
        event_id: event.event_id,
        label: `${event.away_team} @ ${event.home_team}`,
        reason: "model_context_failed",
        detail: "predict threw: " + String((e as Error)?.message ?? e),
      });
      continue;
    }

    let built = 0;
    for (const p of preds) {
      if (!model.supportsMarket(p.market, p.selection)) {
        telemetry.skipped.push({
          event_id: event.event_id,
          label: `${event.away_team} @ ${event.home_team} · ${p.market}`,
          reason: "unsupported_market",
          detail: `unsupported_by_model: ${model.modelVersion} does not model ${p.market}`,
        });
        continue;
      }
      const r = buildRow(model.modelVersion, event, market.event, p, {
        dataAsOf: ctx.dataAsOf ?? null,
        featureSnapshotId: ctx.featureSnapshotId ?? null,
      });
      if (!r.ok || !r.row) {
        telemetry.skipped.push({
          event_id: event.event_id,
          label: `${event.away_team} @ ${event.home_team} · ${p.market} ${p.selection}`,
          reason: (r.reason as SkipEntry["reason"]) ?? "invalid_probability",
          detail: r.detail,
        });
        continue;
      }
      rows.push(r.row);
      built++;
    }
    if (built > 0) telemetry.predicted++;
  }

  const { kept, dropped } = dedupeRows(rows);
  for (const dRow of dropped) {
    telemetry.skipped.push({
      event_id: dRow.event_id,
      label: `${dRow.away_team} @ ${dRow.home_team} · ${dRow.market} ${dRow.selection}`,
      reason: "duplicate_event",
      detail: "a second row for the same (model_version, event_id, market, selection) was produced in one run",
    });
  }

  telemetry.rows_built = kept.length;
  const predictedIds = new Set(kept.map((r) => r.event_id));
  telemetry.matched_events = predictedIds.size;
  /* A captured event that produced no row. This is the line that makes a future
     join break visible IN THE RUN rather than three weeks later in the record —
     it is how the doubleheader bug would have been caught on day one. */
  telemetry.unmatched_events = marketEvents
    .filter((e) => !predictedIds.has(e.event_id))
    .slice(0, 10)
    .map((e) => ({ event_id: e.event_id, game: `${e.away_team} @ ${e.home_team}`, commence_time: e.commence_time }));

  if (model.telemetryExtra) telemetry.extra = model.telemetryExtra(kept, ctx);

  return { telemetry, rows: kept, samples: kept.slice(0, 3) };
}

export interface RunOptions {
  dry: boolean;
  sportFilter?: string | null;
  upsert: (rows: unknown[]) => Promise<number>;
}

export async function runAll(deps: ModelDeps, opts: RunOptions) {
  const keys = REGISTERED_SPORTS.filter((k) => {
    if (!opts.sportFilter) return true;
    return k === opts.sportFilter;
  });

  const sports: Record<string, SportTelemetry> = {};
  const errors: Array<{ sport: string; error: string }> = [];
  const samples: PredictionRow[] = [];
  let rowsBuilt = 0, rowsWritten = 0, scheduled = 0, predicted = 0;

  for (const key of keys) {
    const model = MODEL_REGISTRY[key];
    try {
      const res = await runSport(deps, key, model);
      if (!opts.dry && res.rows.length) {
        res.telemetry.rows_written = await opts.upsert(res.rows);
      }
      sports[key] = res.telemetry;
      rowsBuilt += res.telemetry.rows_built;
      rowsWritten += res.telemetry.rows_written;
      scheduled += res.telemetry.scheduled;
      predicted += res.telemetry.predicted;
      samples.push(...res.samples);
    } catch (e) {
      /* One sport's data problem is isolated here. It is reported, not swallowed,
         and the remaining sports still run. */
      const msg = String((e as Error)?.message ?? e);
      errors.push({ sport: key, error: msg });
      sports[key] = {
        model_version: model.modelVersion,
        ui_label: model.uiLabel,
        status: "error",
        scheduled: 0, eligible: 0, predicted: 0, skipped: [],
        rows_built: 0, rows_written: 0,
        market_events: 0, matched_events: 0, unmatched_events: [],
        data_quality: { status: "error", detail: msg, contract: model.dataContract },
        error: msg,
      };
      deps.log("sport run failed", { sport: key, error: msg });
    }
  }

  return { sports, errors, samples, rowsBuilt, rowsWritten, scheduled, predicted };
}

// ---------------------------------------------------------------------------
// core/calibrate.ts
// ---------------------------------------------------------------------------
// ============================================================================
// EdgeDesk : model_predict / core / calibrate
//
// Where a model's feature weights come from. Nowhere else.
//
// THE RULE THIS FILE EXISTS TO ENFORCE: a feature may influence a probability
// only if a coefficient for it was fitted on outcomes the model could not see
// at prediction time. Everything here is WALK-FORWARD — features for a match
// are computed from the state BEFORE that match, then the state is updated —
// and the holdout is the chronological tail, never a random split.
//
// WHAT IS DELIBERATELY EXCLUDED, AND WHY.
// UFC's career striking and grappling averages (SLpM, takedown defence, style
// indices) are career-TO-DATE values as of today. Using them to predict a fight
// from 2019 lets the model see how that fight went. There is no time-sliced
// version of those columns in the ufc schema and none can be reconstructed from
// ufc.fighter_fights, which carries no strike counts. So they are computed and
// stored on every prediction for audit, and they are NOT fitted and NOT applied.
// Fitting them would produce a model that looks excellent in backtest and is
// worth nothing live, which is the single most common way a sports model lies.
//
// Tennis rankings are excluded from the fit for the same reason:
// tennis.rankings_current holds today's ranking only. Ranking still does real
// work as a COLD START for players with too few matches to rate, where it is
// applied to an upcoming match and is not retrospective.
//
// MLB is not calibratable here: mlb_runs_v1.2_nbinom_dh is a frozen baseline
// and its constants change only through a new model version. NFL and WNBA have
// no owned history to fit against at all.
// ============================================================================

export interface CalibrateResult {
  ok: boolean;
  model_version?: string;
  reason?: string;
  fit?: {
    features: string[];
    weights: number[];
    intercept: number;
    n_train: number;
    n_test: number;
    train: unknown;
    test: unknown;
    converged: boolean;
  };
  /** the self-calibrating baseline's score on the same holdout, so a fit that
   *  does not beat plain Elo can be seen to not beat plain Elo */
  baseline?: unknown;
  reliability?: unknown;
  written?: boolean;
  note?: string;
}

export interface CalibrateDeps {
  dry: boolean;
  upsert?: (table: string, rows: unknown[], onConflict: string, resolution?: "merge-duplicates" | "ignore-duplicates") => Promise<number>;
}

export async function calibrate(
  deps: ModelDeps,
  registryKey: string,
  model: SportPredictionModel,
  opts: { dry: boolean; upsert?: CalibrateDeps["upsert"] },
): Promise<CalibrateResult> {
  if (registryKey === "baseball_mlb") {
    return {
      ok: false,
      model_version: model.modelVersion,
      reason: "mlb_runs_v1.2_nbinom_dh is a frozen baseline. Its constants change only by cutting a new model version, never by refitting in place.",
    };
  }
  if (registryKey === "americanfootball_nfl" || registryKey === "basketball_wnba") {
    return {
      ok: false,
      model_version: model.modelVersion,
      reason: `No owned historical result table for ${registryKey}. Populate the team-features table and a game-results history before calibration is meaningful.`,
    };
  }
  if (registryKey === "tennis_atp") return calibrateTennis(deps, ATP_PARAMS, opts);
  if (registryKey === "tennis_wta") return calibrateTennis(deps, WTA_PARAMS, opts);
  if (registryKey === "mma_mixed_martial_arts") return calibrateUfc(deps, opts);
  return { ok: false, reason: `no calibration routine for ${registryKey}` };
}

async function pagedSchemaForCalibration(deps: ModelDeps, schema: string, base: string, order: string, maxPages = 60): Promise<any[]> {
  const out: any[] = [];
  const PAGE = 1000;
  for (let p = 0; p < maxPages; p++) {
    const rows = await deps.sbGetSchema(schema, `${base}&order=${order}&limit=${PAGE}&offset=${p * PAGE}`);
    if (!rows || !rows.length) break;
    out.push(...rows);
    if (rows.length < PAGE) break;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Tennis
// ---------------------------------------------------------------------------

async function calibrateTennis(
  deps: ModelDeps,
  params: TourParams,
  opts: { dry: boolean; upsert?: CalibrateDeps["upsert"] },
): Promise<CalibrateResult> {
  const cutoff = new Date(deps.now.getTime() - params.historyYears * 365.25 * 86400000)
    .toISOString().slice(0, 10);
  let matches: TennisMatchRow[];
  try {
    matches = await pagedSchemaForCalibration(
      deps, "tennis",
      `matches?select=match_id,match_date,tourney_name,surface,level,round,winner_id,loser_id,minutes&tour=eq.${params.tour}&match_date=gte.${cutoff}`,
      "match_date.asc,match_id.asc",
    ) as TennisMatchRow[];
  } catch (e) {
    return { ok: false, model_version: params.modelVersion, reason: String((e as Error)?.message ?? e) };
  }
  if (matches.length < 2000) {
    return {
      ok: false,
      model_version: params.modelVersion,
      reason: `only ${matches.length} ${params.tour} matches in the last ${params.historyYears}y; need >= 2000 to fit and still hold out a tail.`,
    };
  }

  matches.sort((a, b) =>
    String(a.match_date).localeCompare(String(b.match_date)) ||
    String(a.match_id ?? "").localeCompare(String(b.match_id ?? "")));

  const overall = newElo(params.elo);
  const bySurface: Record<string, EloState> = {};
  const recent = new Map<string, Array<{ date: string; won: boolean; minutes: number | null }>>();
  const h2h = new Map<string, { a: number; b: number }>();

  const rows: number[][] = [];
  const labels: number[] = [];
  const baselineProbs: number[] = [];

  for (const m of matches) {
    const w = m.winner_id != null ? String(m.winner_id) : "";
    const l = m.loser_id != null ? String(m.loser_id) : "";
    if (!w || !l || w === l) continue;
    const date = String(m.match_date);
    const surf = normSurface(m.surface);

    /* Side A is the alphabetically-first id. Deterministic, and independent of
       who won, so the label is not encoded in the ordering. */
    const A = w < l ? w : l;
    const B = w < l ? l : w;
    const label = A === w ? 1 : 0;

    const sA = strengthAt(overall, bySurface, params, A, surf);
    const sB = strengthAt(overall, bySurface, params, B, surf);
    const rated = matchesOf(overall, A) >= params.minMatches && matchesOf(overall, B) >= params.minMatches;

    if (rated) {
      const fA = formAt(recent, A, date);
      const fB = formAt(recent, B, date);
      const hk = A + "|" + B;
      const hh = h2h.get(hk) ?? { a: 0, b: 0 };
      rows.push([
        sA.rating - sB.rating,
        sA.surfaceRating - sB.surfaceRating,
        (fA.rest ?? 0) - (fB.rest ?? 0),
        fA.matches14 - fB.matches14,
        (fA.form10 ?? 0.5) - (fB.form10 ?? 0.5),
        hh.a - hh.b,
      ]);
      labels.push(label);
      baselineProbs.push(eloProb(sA.rating - sB.rating, params.elo.scale));
    }

    // ---- state update happens AFTER the features are read ----
    updateElo(overall, w, l, date);
    if (surf !== "unknown") {
      const st = bySurface[surf] || (bySurface[surf] = newElo(params.elo));
      updateElo(st, w, l, date);
    }
    const mins = m.minutes != null && Number.isFinite(+m.minutes) ? +m.minutes : null;
    pushForm(recent, w, { date, won: true, minutes: mins });
    pushForm(recent, l, { date, won: false, minutes: mins });
    const hk2 = w < l ? w + "|" + l : l + "|" + w;
    const cur = h2h.get(hk2) ?? { a: 0, b: 0 };
    if (w < l) cur.a++; else cur.b++;
    h2h.set(hk2, cur);
  }

  if (rows.length < 500) {
    return {
      ok: false,
      model_version: params.modelVersion,
      reason: `only ${rows.length} matches had both players rated (>= ${params.minMatches} career matches). Load more history.`,
    };
  }

  const fit = fitLogistic(TENNIS_FIT_FEATURES, rows, labels, { l2: 2.0, iterations: 6000, learningRate: 0.2 });
  if (!fit) return { ok: false, model_version: params.modelVersion, reason: "fit did not converge on a usable sample" };

  const nTest = fit.nTest;
  const baselineTail = baselineProbs.slice(baselineProbs.length - nTest);
  const labelTail = labels.slice(labels.length - nTest);
  const baseline = metrics(baselineTail, labelTail);

  const written = await storeParams(opts, params.modelVersion, {
    elo: params.elo,
    surface_max_weight: params.surfaceMaxWeight,
    blend: {
      featureNames: fit.featureNames,
      weights: fit.weights,
      intercept: fit.intercept,
      mean: fit.mean,
      sd: fit.sd,
    },
  }, fit, baseline);

  return {
    ok: true,
    model_version: params.modelVersion,
    fit: summarise(fit),
    baseline,
    reliability: reliability(baselineTail, labelTail),
    written,
    note: fit.test.logLoss < (baseline as { logLoss: number }).logLoss
      ? "fitted model beats plain Elo on the holdout"
      : "fitted model does NOT beat plain Elo on the holdout — it is stored, but predict() will still be strictly worse than the baseline until the feature set improves. Consider deleting the model_parameters row.",
  };
}

function strengthAt(
  overall: EloState,
  bySurface: Record<string, EloState>,
  params: TourParams,
  id: string,
  surface: string,
) {
  const o = ratingOf(overall, id);
  const st = bySurface[surface];
  const sMatches = st ? matchesOf(st, id) : 0;
  const sRating = st ? ratingOf(st, id) : o;
  const b = blendedRating(o, sRating, sMatches, params.surfaceMaxWeight, params.surfaceFullAt);
  return { rating: b.rating, surfaceRating: sRating, overall: o };
}

function pushForm(
  map: Map<string, Array<{ date: string; won: boolean; minutes: number | null }>>,
  id: string,
  row: { date: string; won: boolean; minutes: number | null },
) {
  const arr = map.get(id) ?? [];
  arr.push(row);
  if (arr.length > 40) arr.shift();
  map.set(id, arr);
}

function formAt(
  map: Map<string, Array<{ date: string; won: boolean; minutes: number | null }>>,
  id: string,
  asOf: string,
) {
  const hist = map.get(id) ?? [];
  const last = hist.length ? hist[hist.length - 1] : null;
  const rest = last ? daysBetween(last.date, asOf) : null;
  const t = Date.parse(asOf);
  let m14 = 0, wins = 0, n = 0;
  for (let i = hist.length - 1; i >= 0; i--) {
    const d = Date.parse(hist[i].date);
    if (Number.isFinite(t) && Number.isFinite(d)) {
      const days = (t - d) / 86400000;
      if (days >= 0 && days <= 14) m14++;
    }
    if (n < 10) { n++; if (hist[i].won) wins++; }
  }
  return { rest, matches14: m14, form10: n ? wins / n : null };
}

// ---------------------------------------------------------------------------
// UFC
// ---------------------------------------------------------------------------

async function calibrateUfc(
  deps: ModelDeps,
  opts: { dry: boolean; upsert?: CalibrateDeps["upsert"] },
): Promise<CalibrateResult> {
  let fights: any[];
  let fighters: any[];
  try {
    fights = await pagedSchemaForCalibration(deps, "ufc", "fighter_fights?select=fighter_id,opponent_id,date,winner", "date.asc", 40);
    fighters = await pagedSchemaForCalibration(deps, "ufc", "fighters?select=fighter_id,stance,reach_inches,age", "fighter_id", 20);
  } catch (e) {
    return { ok: false, model_version: UFC_MODEL_VERSION, reason: String((e as Error)?.message ?? e) };
  }

  const bio = new Map<string, { stance: string; reach: number | null; age: number | null }>();
  for (const f of fighters) {
    if (f?.fighter_id == null) continue;
    bio.set(String(f.fighter_id), {
      stance: String(f.stance ?? "").toLowerCase(),
      reach: f.reach_inches != null && Number.isFinite(+f.reach_inches) ? +f.reach_inches : null,
      age: f.age != null && Number.isFinite(+f.age) ? +f.age : null,
    });
  }

  // Deduplicate the two corner rows per bout, exactly as the model does.
  let idLike = 0, resultLike = 0;
  for (const r of fights) {
    const s = String(r?.winner ?? "").toLowerCase();
    if (s === "win" || s === "loss" || s === "w" || s === "l") resultLike++;
    else if (String(r?.fighter_id) === String(r?.winner) || String(r?.opponent_id) === String(r?.winner)) idLike++;
  }
  const semantics = idLike >= resultLike && idLike > 0 ? "winner_id" : resultLike > 0 ? "result_string" : "unknown";
  if (semantics === "unknown") {
    return { ok: false, model_version: UFC_MODEL_VERSION, reason: "ufc.fighter_fights.winner is neither a fighter id nor a W/L result" };
  }

  const seen = new Set<string>();
  const bouts: Array<{ date: string; winner: string; loser: string }> = [];
  for (const r of fights) {
    const a = r?.fighter_id != null ? String(r.fighter_id) : "";
    const b = r?.opponent_id != null ? String(r.opponent_id) : "";
    const date = r?.date ? String(r.date) : "";
    if (!a || !b || a === b || !date) continue;
    const key = (a < b ? a + "|" + b : b + "|" + a) + "|" + date;
    if (seen.has(key)) continue;
    let winner: string | null = null;
    if (semantics === "winner_id") {
      const w = String(r.winner ?? "");
      if (w === a) winner = a; else if (w === b) winner = b;
    } else {
      const s = String(r.winner ?? "").toLowerCase();
      if (s === "win" || s === "w") winner = a; else if (s === "loss" || s === "l") winner = b;
    }
    if (!winner) continue;
    seen.add(key);
    bouts.push({ date, winner, loser: winner === a ? b : a });
  }
  bouts.sort((x, y) => x.date.localeCompare(y.date));

  if (bouts.length < 1500) {
    return { ok: false, model_version: UFC_MODEL_VERSION, reason: `only ${bouts.length} resolvable bouts; need >= 1500.` };
  }

  const elo = newElo({ initial: 1500, kFactor: 120, kShift: 4, kDecay: 0.35, scale: 400 });
  const lastFight = new Map<string, string>();
  const rows: number[][] = [];
  const labels: number[] = [];
  const baselineProbs: number[] = [];
  const nowMs = deps.now.getTime();

  for (const b of bouts) {
    const A = b.winner < b.loser ? b.winner : b.loser;
    const B = b.winner < b.loser ? b.loser : b.winner;
    const label = A === b.winner ? 1 : 0;

    if (matchesOf(elo, A) >= 3 && matchesOf(elo, B) >= 3) {
      const bioA = bio.get(A), bioB = bio.get(B);
      const eloDiff = ratingOf(elo, A) - ratingOf(elo, B);
      const reach = (bioA?.reach ?? 0) - (bioB?.reach ?? 0);
      /* Age is reconstructed AS OF the bout: the stored age is today's, so the
         years elapsed since the fight are subtracted back off. Using today's
         age directly would leak the passage of time into an old fight. */
      const yearsAgo = (nowMs - Date.parse(b.date)) / (365.25 * 86400000);
      const ageA = bioA?.age != null ? bioA.age - yearsAgo : null;
      const ageB = bioB?.age != null ? bioB.age - yearsAgo : null;
      const ageDiff = (ageA ?? 0) - (ageB ?? 0);
      const layA = daysBetween(lastFight.get(A) ?? null, b.date);
      const layB = daysBetween(lastFight.get(B) ?? null, b.date);
      const layoff = (layA ?? 0) - (layB ?? 0);
      let stance = 0;
      if (bioA?.stance && bioB?.stance) {
        const aS = bioA.stance.indexOf("southpaw") >= 0;
        const bS = bioB.stance.indexOf("southpaw") >= 0;
        stance = aS === bS ? 0 : (aS ? 1 : -1);
      }
      rows.push([eloDiff, reach, ageDiff, layoff, stance]);
      labels.push(label);
      baselineProbs.push(eloProb(eloDiff, 400));
    }

    updateElo(elo, b.winner, b.loser, b.date);
    lastFight.set(b.winner, b.date);
    lastFight.set(b.loser, b.date);
  }

  if (rows.length < 500) {
    return { ok: false, model_version: UFC_MODEL_VERSION, reason: `only ${rows.length} bouts had both fighters rated. Load more history.` };
  }

  const fit = fitLogistic(UFC_FIT_FEATURES, rows, labels, { l2: 2.0, iterations: 6000, learningRate: 0.2 });
  if (!fit) return { ok: false, model_version: UFC_MODEL_VERSION, reason: "fit did not converge on a usable sample" };

  const baselineTail = baselineProbs.slice(baselineProbs.length - fit.nTest);
  const labelTail = labels.slice(labels.length - fit.nTest);
  const baseline = metrics(baselineTail, labelTail);

  const written = await storeParams(opts, UFC_MODEL_VERSION, {
    blend: {
      featureNames: fit.featureNames,
      weights: fit.weights,
      intercept: fit.intercept,
      mean: fit.mean,
      sd: fit.sd,
    },
  }, fit, baseline);

  return {
    ok: true,
    model_version: UFC_MODEL_VERSION,
    fit: summarise(fit),
    baseline,
    reliability: reliability(baselineTail, labelTail),
    written,
    note: "career striking/grappling/style features are deliberately NOT fitted: ufc.fighter_career_stats holds career-to-date values only, so using them on a past bout would leak that bout's result into its own prediction. They remain in model_detail for audit.",
  };
}

function summarise(fit: FitResult) {
  return {
    features: fit.featureNames,
    weights: fit.weights.map((w) => +w.toFixed(5)),
    intercept: +fit.intercept.toFixed(5),
    n_train: fit.nTrain,
    n_test: fit.nTest,
    train: fit.train,
    test: fit.test,
    converged: fit.converged,
  };
}

async function storeParams(
  opts: { dry: boolean; upsert?: CalibrateDeps["upsert"] },
  modelVersion: string,
  params: Record<string, unknown>,
  fit: FitResult,
  baseline: unknown,
): Promise<boolean> {
  if (opts.dry || !opts.upsert) return false;
  await opts.upsert("model_parameters", [{
    model_version: modelVersion,
    param_set: "default",
    params,
    n_train: fit.nTrain,
    n_test: fit.nTest,
    metrics: { train: fit.train, test: fit.test, baseline },
  }], "model_version,param_set", "merge-duplicates");
  return true;
}

// ---------------------------------------------------------------------------
// index.ts
// ---------------------------------------------------------------------------
// ============================================================================
// EdgeDesk : model_predict  —  multi-sport prediction engine
//
// WHAT THIS FUNCTION IS. It answers one question per market: what does the
// model believe the probability is? It does NOT decide BET / WAIT / PASS. That
// belongs to EdgeDesk's research and decision layer, which is downstream and
// stays downstream (spec §22). It also never calls an LLM: every probability
// here comes out of a deterministic statistical process, and an LLM may one day
// explain a prediction but will never compute one (spec §23).
//
// SPORTS
//     baseball_mlb            mlb_runs_v1.2_nbinom_dh   (the frozen baseline)
//     tennis_atp*             atp_match_v1
//     tennis_wta*             wta_match_v1
//     mma_mixed_martial_arts  ufc_fight_v1
//     americanfootball_nfl*   nfl_game_v1
//     basketball_wnba         wnba_game_v1
//
// MODES
//     ?dry=1            run everything, write nothing. Deployment validation.
//     ?sport=<key>      one sport only. Accepts a registry key, a captured
//                       sport_key, or the UI label (MLB/ATP/WTA/MMA/NFL/WNBA).
//     ?seed=12345       deterministic simulation, for reproducible tests.
//     ?registry=1       publish the model registry and every data contract.
//     ?calibrate=1      fit tour/sport parameters on owned history and store
//                       them. Requires ?sport=. Never runs implicitly.
//
// THE CLV BASELINE IS SACRED. The first prediction for
// (model_version, event_id, market, selection) is the entry snapshot, and
// re-running this function must never overwrite it. That is enforced by the
// unique index plus `Prefer: resolution=ignore-duplicates` in core/db.ts.
// Removing either destroys EdgeDesk's ability to measure CLV, calibration or
// ROI after the fact.
//
// DEPLOY
//     supabase functions deploy model_predict --no-verify-jwt
//     then: curl "$URL/functions/v1/model_predict?dry=1"
// ============================================================================

const SB_URL = env("SUPABASE_URL");
const SB_SERVICE = env("SUPABASE_SERVICE_ROLE_KEY");
const CRON_SECRET = env("CRON_SECRET");

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body, null, 2), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

(globalThis as any).Deno?.serve?.(async (req: Request): Promise<Response> => {
  const started = Date.now();
  try {
    const url = new URL(req.url);
    const q = url.searchParams;
    const dry = q.get("dry") === "1";
    const wantRegistry = q.get("registry") === "1";
    const wantCalibrate = q.get("calibrate") === "1";
    const sportArg = q.get("sport");
    const seedArg = q.get("seed");

    if (wantRegistry) {
      return json({ ok: true, registry: describe() });
    }

    /* Anything that WRITES is gated. A dry run is read-only and stays open so
       deployment validation does not need the secret. */
    if ((!dry || wantCalibrate) && CRON_SECRET && req.headers.get("x-cron-secret") !== CRON_SECRET) {
      return json({ ok: false, error: "forbidden" }, 403);
    }
    if (!SB_URL || !SB_SERVICE) {
      return json({ ok: false, error: "SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set" }, 500);
    }

    const db = makeDb({ url: SB_URL, serviceKey: SB_SERVICE });
    const now = new Date();
    const etDate = new Intl.DateTimeFormat("en-CA", {
      timeZone: "America/New_York",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(now);

    const seed = seedArg != null && seedArg !== "" ? Number(seedArg) : undefined;
    if (seedArg != null && seedArg !== "" && !Number.isFinite(seed)) {
      return json({ ok: false, error: `seed is not a number: ${seedArg}` }, 400);
    }
    const rng = makeRng(seed);

    const logs: Array<{ msg: string; extra?: Record<string, unknown> }> = [];
    const deps: ModelDeps = {
      sbGet: db.sbGet,
      sbGetSchema: db.sbGetSchema,
      jget: db.jget,
      rng,
      etDate,
      now,
      pmap,
      log: (msg, extra) => {
        if (logs.length < 200) logs.push({ msg, extra });
      },
    };

    // ---- resolve the sport filter -----------------------------------------
    let filterKey: string | null = null;
    if (sportArg) {
      const m = resolveFilter(sportArg);
      if (!m) {
        return json({
          ok: false,
          error: `unknown sport: ${sportArg}`,
          known: REGISTERED_SPORTS.map((k) => ({ key: k, label: MODEL_REGISTRY[k].uiLabel })),
        }, 400);
      }
      filterKey = REGISTERED_SPORTS.find((k) => MODEL_REGISTRY[k] === m) ?? null;
    }

    // ---- calibration -------------------------------------------------------
    if (wantCalibrate) {
      if (!filterKey) {
        return json({ ok: false, error: "?calibrate=1 requires ?sport=<key>. Calibration is per model, never implicit." }, 400);
      }
      const res = await calibrate(deps, filterKey, MODEL_REGISTRY[filterKey], { dry, upsert: db.upsert });
      return json({ dry, sport: filterKey, ...res }, res.ok ? 200 : 422);
    }

    // ---- the run -----------------------------------------------------------
    const out = await runAll(deps, { dry, sportFilter: filterKey, upsert: db.upsertPredictions });

    const modelVersions = Object.keys(out.sports).map((k) => out.sports[k].model_version);
    const dataQuality: Record<string, unknown> = {};
    for (const k of Object.keys(out.sports)) dataQuality[k] = out.sports[k].data_quality;

    return json({
      ok: true,
      dry,
      seed: rng.seed,
      et_date: etDate,
      elapsed_ms: Date.now() - started,
      model_versions: modelVersions,
      sports: out.sports,
      games_scheduled: out.scheduled,
      predicted_games: out.predicted,
      rows_built: out.rowsBuilt,
      rows_written: dry ? 0 : out.rowsWritten,
      skipped: Object.keys(out.sports).flatMap((k) =>
        out.sports[k].skipped.slice(0, 25).map((s) => ({ sport: k, ...s }))
      ),
      errors: out.errors,
      data_quality: dataQuality,
      samples: out.samples.slice(0, 12),
      logs: logs.slice(0, 40),
    });
  } catch (e) {
    return json({ ok: false, error: String((e as Error)?.message ?? e) }, 500);
  }
});

// Re-exported so a consumer (or a test) can reach the pieces without booting
// the HTTP handler.
